SELECT now() "observedAt",(SELECT jsonb_agg(jsonb_build_object('id',p.id,'sku',p.sku,'vatDepartmentId',p."vatDepartmentId",'vatRate',p."vatRate",'vatVerified',p."vatVerified",'protected',md5((to_jsonb(p)-'vatDepartmentId'-'vatRate'-'vatVerified'-'updatedAt')::text),'stock',sp."currentStock",'price',sp."salePrice",'storeHash',md5(to_jsonb(sp)::text))) FROM "Product" p JOIN "StoreProduct" sp ON sp."productId"=p.id WHERE (sp."storeId"='kat-store' OR sp."storeId"='cmtpopbgo000trhb5ng9ytiru' AND p.sku='LAB-CAFE-20260927')) catalog,(SELECT jsonb_agg(to_jsonb(d)) FROM "ManagementVatDepartment" d WHERE d."companyId"='cmtpopbgk000prhb5qc60zxus') departments